    ("segment_history", "book_id=?"),
    ("chapter_text", "book_id=?"),
    ("chapter_renders", "chapter_id IN (SELECT id FROM chapters WHERE book_id=?)"),
    ("segments", "book_id=?"),
    ("chapters", "book_id=?"),
