}
export async function confirmDialog(title, message, okLabel = "Confirm", danger = false) {
  const v = await dialog({ title, body: html`<p>${message}</p>`, buttons: [{ label: okLabel, value: "ok", kind: danger ? "danger" : "primary" }] });
