@pytest.mark.parametrize("name", ["../evil.zip", "..\\evil.zip", "/etc/passwd.zip", "sub/dir.zip", "C:\\x.zip", "no-extension", "a..b/../c.zip", ".hidden.zip"])
def test_restore_rejects_bad_names(client, name):
